/**
 * List jobs for current user with cursor pagination.
 * @summary List Jobs
 */
export const listJobsQueryLimitDefault = 10;
export const listJobsQueryLimitMax = 50;

export const listJobsQueryParams = zod.object({
  "status": zod.union([zod.string(),zod.null()]).optional(),
  "type": zod.union([zod.string(),zod.null()]).optional(),
  "limit": zod.number().min(1).max(listJobsQueryLimitMax).default(listJobsQueryLimitDefault),
  "cursor": zod.union([zod.string(),zod.null()]).optional()
})

export const listJobsResponseJobsItemProgressMsgDefault = "";export const listJobsResponseJobsItemCancelRequestedDefault = false;export const listJobsResponseJobsItemRetryableDefault = true;

export const listJobsResponse = zod.object({
  "jobs": zod.array(zod.object({
  "id": zod.string(),
  "type": zod.string(),
  "status": zod.enum(['queued', 'running', 'completed', 'failed', 'cancelled']),
  "roundNumber": zod.union([zod.number(),zod.null()]).optional(),
  "query": zod.union([zod.string(),zod.null()]).optional(),
  "progress": zod.union([zod.object({
  "step": zod.number(),
  "total": zod.number(),
  "msg": zod.string().optional()
}),zod.null()]).optional(),
  "cancelRequested": zod.boolean().optional(),
  "createdAt": zod.iso.datetime({}),
  "startedAt": zod.union([zod.iso.datetime({}),zod.null()]).optional(),
  "completedAt": zod.union([zod.iso.datetime({}),zod.null()]).optional(),
  "error": zod.union([zod.string(),zod.null()]).optional(),
  "retryable": zod.boolean().default(listJobsResponseJobsItemRetryableDefault),
  "tokenCount": zod.union([zod.number(),zod.null()]).optional(),
  "model": zod.union([zod.string(),zod.null()]).optional()
}).describe('Job status response for polling.')).optional(),
  "nextCursor": zod.union([zod.string(),zod.null()]).optional()
}).describe('List of jobs for user dashboard.')
